/*:
* @target MZ
* @plugindesc Checks if the game is ending and updates a variable before it ends or closes the window.
*
@Author
WisePot
*
*
@param
GameVariableID
* @text Variable ID
* @type variable
*
@Default
1
*
@desc
The game variable ID to update before the game ends or is closed.
*
*
@Help
* This plugin detects when the game is ending (via "End Game" or closing the window)
* and updates a specified variable before the game exits.
*
* No plugin commands are required.
*/
(() => {
const parameters = PluginManager.parameters('WisePotGameEndCheck');
const variableId = Number(parameters['GameVariableID'] || 1);
const originalEndCommand = Scene_GameEnd.prototype.commandToTitle;
const originalTerminate = SceneManager.terminate;
let isGameEnding = false;
// Function to set the variable before ending
const setGameEndVariable = () => {
if ($gameVariables) {
$gameVariables.setValue(variableId, 1); // Set the variable to a value (e.g., 1)
console.log(`Game variable ${variableId} set to 1 before ending.`);
}
};
// Hook into the "End Game" command
Scene_GameEnd.prototype.commandToTitle = function () {
if (!isGameEnding) {
setGameEndVariable();
}
isGameEnding = true;
originalEndCommand.call(this);
};
// Hook into SceneManager terminate
SceneManager.terminate = function () {
if (!isGameEnding) {
setGameEndVariable();
}
isGameEnding = true; // Mark as ending
originalTerminate.call(this);
};
})();
